-- @case 1: person 1 has all four roles: Employee (Buyer), Vendor Contact (Owner), Store Contact (Purchasing Manager), Consumer; being also a store's customer adds no second Consumer row
BEGIN;
DELETE FROM humanresources.employee;
DELETE FROM person.business_entity_contact;
DELETE FROM person.contact_type;
DELETE FROM person.person;
DELETE FROM purchasing.vendor;
DELETE FROM sales.customer;
DELETE FROM sales.store;
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM dbo.ufn_get_contact_information('1'::integer);
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['PersonID', 'FirstName', 'LastName', 'JobTitle', 'BusinessEntityType']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 person 1 has all four roles: Employee (Buyer), Vendor Contact (Owner), Store Contact (Purchasing Mana…', got, ARRAY['PersonID', 'FirstName', 'LastName', 'JobTitle', 'BusinessEntityType']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 person 1 has all four roles: Employee (Buyer), Vendor Contact (Owner), Store Contact (Purchasing Mana…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;

